function Get-FolderSizeGB($path) { if (-not (Test-Path $path)) { return $null }; $sum = (Get-ChildItem $path -Force -ErrorAction SilentlyContinue | ForEach-Object { if ($_.PSIsContainer) { (Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } else { $_.Length } } | Measure-Object -Sum).Sum; [math]::Round(($sum ?? 0)/1GB, 2) }
$roots = @('C:\Windows','C:\Program Files','C:\Program Files (x86)','C:\ProgramData','C:\Users','C:\$Recycle.Bin','C:\System Volume Information')
foreach ($r in $roots) { Write-Output ("{0}`t{1} GB" -f $r, (Get-FolderSizeGB $r)) }

$paths = @('C:\Windows','C:\Program Files','C:\Program Files (x86)','C:\ProgramData','C:\Users')
foreach ($p in $paths) {
  $sum = 0
  if (Test-Path $p) {
    Get-ChildItem $p -Force -ErrorAction SilentlyContinue | ForEach-Object {
      if ($_.PSIsContainer) {
        $sum += (Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
      } else { $sum += $_.Length }
    }
  }
  Write-Output ("{0,-30} {1,8} GB" -f $p, [math]::Round($sum/1GB,2))
}

$winSub = @('System32','WinSxS','SoftwareDistribution','Installer','Temp','Logs','System32\DriverStore','servicing')
foreach ($s in $winSub) {
  $p = Join-Path 'C:\Windows' $s
  if (Test-Path $p) {
    $sum = (Get-ChildItem $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    Write-Output ("{0,-35} {1,8} GB" -f $s, [math]::Round($sum/1GB,2))
  }
}

$tempPaths = @($env:TEMP, "$env:LOCALAPPDATA\Temp", "C:\Windows\Temp")
$freed = 0
foreach ($tp in $tempPaths) {
  if (Test-Path $tp) {
    Get-ChildItem $tp -Force -ErrorAction SilentlyContinue | ForEach-Object {
      try {
        $sz = if ($_.PSIsContainer) { (Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } else { $_.Length }
        Remove-Item $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
        $freed += $sz
      } catch {}
    }
  }
}
"Temp cleaned: $([math]::Round($freed/1GB,2)) GB"

$dl = "$env:USERPROFILE\Downloads"
$removed = @()
$freed = 0
Get-ChildItem $dl -File -Force -ErrorAction SilentlyContinue | Where-Object {
  $_.Extension -match '^\.(exe|msi)$' -or ($_.Extension -eq '.zip' -and $_.Length -gt 100MB)
} | ForEach-Object {
  try {
    $freed += $_.Length
    $removed += $_.Name
    Remove-Item $_.FullName -Force -ErrorAction Stop
  } catch {
    $removed += "FAILED: $($_.Name)"
  }
}
"Downloads removed $($removed.Count) files, freed $([math]::Round($freed/1GB,2)) GB"
$removed | ForEach-Object { "  - $_" }

function Clear-DirContents($path, $label) {
  if (-not (Test-Path $path)) { return 0 }
  $freed = 0
  Get-ChildItem $path -Force -ErrorAction SilentlyContinue | ForEach-Object {
    try {
      $sz = if ($_.PSIsContainer) { (Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } else { $_.Length }
      Remove-Item $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
      $freed += $sz
    } catch {}
  }
  Write-Output "$label : $([math]::Round($freed/1GB,2)) GB"
  return $freed
}
$total = 0
$chromeBase = "$env:LOCALAPPDATA\Google\Chrome\User Data"
if (Test-Path $chromeBase) {
  Get-ChildItem $chromeBase -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    foreach ($sub in @('Cache','Code Cache','GPUCache','Service Worker\CacheStorage','Service Worker\ScriptCache')) {
      $p = Join-Path $_.FullName $sub
      $total += (Clear-DirContents $p "Chrome/$($_.Name)/$sub")
    }
  }
}
$total += (Clear-DirContents "$env:APPDATA\LarkShell\aha" "Feishu/aha")
$total += (Clear-DirContents "$env:APPDATA\LarkShell\sdk_storage" "Feishu/sdk_storage")
$total += (Clear-DirContents "$env:LOCALAPPDATA\Kingsoft\WPS Office\cache" "WPS/cache")
$total += (Clear-DirContents "$env:USERPROFILE\.codex\.tmp" "Codex/tmp")
$total += (Clear-DirContents "$env:LOCALAPPDATA\Figma\Cache" "Figma/Cache")
"App cache total freed: $([math]::Round($total/1GB,2)) GB"

function Get-DirSize($path) { if (-not (Test-Path $path)) { return 0 }; (Get-ChildItem $path -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum }
function Wipe-Dir($path) {
  if (-not (Test-Path $path)) { return 0 }
  $before = Get-DirSize $path
  Get-ChildItem $path -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  return $before
}
$report = @()
$paths = @(
  "$env:APPDATA\LarkShell\aha",
  "$env:APPDATA\LarkShell\sdk_storage",
  "$env:LOCALAPPDATA\Kingsoft\WPS Office\cache",
  "$env:USERPROFILE\.codex\.tmp",
  "$env:LOCALAPPDATA\Figma\Cache"
)
foreach ($p in $paths) {
  $f = Wipe-Dir $p
  if ($f -gt 0) { $report += "$p -> $([math]::Round($f/1GB,2)) GB" }
}
$chromeBase = "$env:LOCALAPPDATA\Google\Chrome\User Data"
if (Test-Path $chromeBase) {
  Get-ChildItem $chromeBase -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    foreach ($sub in @('Cache','Code Cache','GPUCache')) {
      $p = Join-Path $_.FullName $sub
      $f = Wipe-Dir $p
      if ($f -gt 0) { $report += "Chrome/$($_.Name)/$sub -> $([math]::Round($f/1GB,2)) GB" }
    }
  }
}
$report
"TOTAL: $([math]::Round(($report | ForEach-Object { [double]($_ -split ' -> ')[1].Replace(' GB','') } | Measure-Object -Sum).Sum, 2)) GB"

function Wipe-Dir($path) {
  if (-not (Test-Path $path)) { return 0 }
  $before = (Get-ChildItem $path -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
  Get-ChildItem $path -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  return $before
}
$extra = @()
$chromeBase = "$env:LOCALAPPDATA\Google\Chrome\User Data"
Get-ChildItem $chromeBase -Directory -ErrorAction SilentlyContinue | ForEach-Object {
  foreach ($sub in @('Cache\Cache_Data','Code Cache\js','Code Cache\wasm','GrShaderCache','ShaderCache','optimization_guide_model_store','BrowserMetrics')) {
    $p = Join-Path $_.FullName $sub
    $f = Wipe-Dir $p
    if ($f -gt 10MB) { $extra += "$sub : $([math]::Round($f/1GB,2)) GB" }
  }
}
$wu = Wipe-Dir "C:\Windows\SoftwareDistribution\Download"
if ($wu -gt 0) { $extra += "WinUpdate Download: $([math]::Round($wu/1GB,2)) GB" }
$npm = Wipe-Dir "$env:APPDATA\npm-cache"
if ($npm -gt 0) { $extra += "npm-cache: $([math]::Round($npm/1GB,2)) GB" }
$pip = Wipe-Dir "$env:LOCALAPPDATA\pip\Cache"
if ($pip -gt 0) { $extra += "pip-cache: $([math]::Round($pip/1GB,2)) GB" }
$extra

Get-Process chrome -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2
